    {
      &quot;href&quot; : &quot;http://c6401.ambari.apache.org:8080/api/v1/action_definitions/hdfs_rebalance_blocks&quot;,
      &quot;ActionDefinitions&quot; : {
        &quot;action_name&quot; : &quot;hdfs_rebalance_blocks&quot;
      }
